import{_ as t,o as n,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Miscellaneous-Mathematics.md","filePath":"manual-zh/Miscellaneous-Mathematics.md","lastUpdated":1785684581000}'),m={name:"manual-zh/Miscellaneous-Mathematics.md"};function o(s,e,u,i,p,_){return n(),a("div",null,[...e[0]||(e[0]=[r('<h4 id="_7-7-2-杂项数学函数" tabindex="-1">7.7.2 杂项数学函数 <a class="header-anchor" href="#_7-7-2-杂项数学函数" aria-label="Permalink to &quot;7.7.2 杂项数学函数&quot;">​</a></h4><p>杂项数学函数接受数值参数并产生数值结果。</p><p>Function: __<strong>ABS</strong> <em>( number)</em></p><p>结果为 number 的绝对值。</p><p>Function: __<strong>MOD</strong> <em>( numerator, denominator)</em></p><p>返回 numerator 除以 denominator 的余数（模）。如果 numerator 为 0，则结果为 0，即使 denominator 为缺失值。如果 denominator 为 0，则结果为系统缺失值。</p><p>Function: __<strong>MOD10</strong> <em>( number)</em></p><p>返回 number 除以 10 的余数。如果 number 为负数，则 MOD10(number) 为负数或零。</p><p>Function: __<strong>RND</strong> <em>( number [, mult[, fuzzbits]])</em></p><p>将 number 舍入到 mult 的倍数（默认为 1）。恰好为一半的值向远离零的方向舍入，number 最低有效位中误差小于 fuzzbits 的、略低于一半的值也同样如此。如果未指定 fuzzbits，则默认值取自 SET FUZZBITS（参见 <a href="./SET#SET-FUZZBITS">SET FUZZBITS</a>），除非被覆盖，否则为 6。</p><p>Function: __<strong>TRUNC</strong> <em>( number [, mult[, fuzzbits]])</em></p><p>将 number 向零方向舍入到 mult 的倍数。对于默认的 mult 为 1 的情况，这等价于丢弃 number 的小数部分。number 最低有效位中误差小于 fuzzbits、略低于 mult 倍数的值向远离零的方向舍入。如果未指定 fuzzbits，则默认值取自 SET FUZZBITS（参见 <a href="./SET#SET-FUZZBITS">SET FUZZBITS</a>），除非被覆盖，否则为 6。</p>',12)])])}const b=t(m,[["render",o]]);export{c as __pageData,b as default};
